/**
 * @jest-environment node
 */
// Conformance with the REAL Studio runtime (contract r17 completeCustomMap).
//
// test/fixtures/studio-product-face-conformance.json is generated by the
// Studio repository (governed-workflow-studio-app) with
//   node scripts/qa/product-face-conformance-fixtures.mjs --out <file>
// at the Studio commit named in its `provenance.studioCommit`. It records,
// from the Studio test world (LOCAL FAKE PROVIDERS, fictional brand, products
// and wallets), on a Studio-minted unit carrying its activation mint keys:
// - the serving release's inspected templates (binding.settle and
//   binding.transferRequest, POST /api/product-face/v1/inspect-templates);
// - the brand's settle proposal and the G8 request step exactly as the
//   runtime answered them, each with the host's fresh read at that moment.
// Regenerate it there (then prettier --write), never edit it here.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { MAX_RESPONSE_BYTES, parseSettleProposal } from "@/api/face-runtime";
import {
  MAX_RAW_BYTES,
  parseProductFaceApplications,
} from "@/api/product-face-binding";
import {
  checkSettleProposal,
  proposalHashInput,
} from "@/app/_domain/product-face";
import {
  checkTransferProposal,
  parseTransferProposal,
  transferProposalHashInput,
} from "@/app/_domain/product-face-transfer";
import { bindingInput, edit, REMOVE } from "@/test/product-face-fixtures";

type Custom = Record<string, unknown>;
/** A runtime answer as recorded (snake case, as on the wire). */
interface Answer extends Record<string, unknown> {
  operation_id: string;
  offer_id: string;
  object_id: string;
  action: string;
  input: { data: { custom: Custom } };
  proposal_hash: string;
}
interface Recorded {
  holder: string;
  now: number;
  fresh: { owner: string; custom: Custom };
  proposal: Answer;
}
interface Fixture {
  schemaVersion: string;
  provenance: { generator: string; studioCommit: string };
  canonicalRegistration: unknown;
  templates: { settle: unknown; transferRequest: unknown };
  settle: Recorded;
  transferRequest: Recorded;
}
const fixture = JSON.parse(
  readFileSync(
    path.join(
      __dirname,
      "../test/fixtures/studio-product-face-conformance.json",
    ),
    "utf8",
  ),
) as Fixture;
const sha = (value: string) =>
  `sha256:${createHash("sha256").update(value).digest("hex")}`;
const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value));

// The Studio templates through the wallet's own strict registry parser.
const [binding] = parseProductFaceApplications(
  JSON.stringify([
    bindingInput({
      canonicalRegistration: fixture.canonicalRegistration,
      settle: fixture.templates.settle,
      transferRequest: fixture.templates.transferRequest,
    }),
  ]),
  { production: true },
);

function settleCheck(answer: Answer, fresh: Custom) {
  const proposal = parseSettleProposal(answer);
  if (!proposal) return "unparsed";
  const result = checkSettleProposal(
    proposal,
    {
      operationId: answer.operation_id,
      objectId: answer.object_id,
      now: fixture.settle.now,
    },
    fresh,
    binding.settle!,
    binding.canonicalRegistration,
  );
  return result.ok && sha(proposalHashInput(proposal)) === answer.proposal_hash
    ? "ok"
    : "rejected";
}

function requestCheck(answer: Answer, fresh: Custom) {
  const proposal = parseTransferProposal(answer);
  if (!proposal) return "unparsed";
  const result = checkTransferProposal(
    proposal,
    {
      offerId: answer.offer_id,
      objectId: answer.object_id,
      holder: fixture.transferRequest.holder,
      now: fixture.transferRequest.now,
      recipientReferenceHash: sha(proposal.recipient),
    },
    { currentCustom: fresh, rules: binding.transferRequest },
  );
  return result.ok &&
    sha(transferProposalHashInput(proposal)) === answer.proposal_hash
    ? "ok"
    : "rejected";
}

/** A variant of a real answer, re-hashed so only the template can refuse it. */
function variant(answer: Answer, change: (custom: Custom) => void) {
  const next = clone(answer);
  change(next.input.data.custom);
  next.proposal_hash = sha(
    proposalHashInput({
      objectId: next.object_id,
      action: next.action,
      input: next.input,
    }),
  );
  return next;
}

const MINT_KEYS = [
  "activation_hash",
  "forge_receipt_hash",
  "builder_pack_schema",
  "dual_asset",
];

describe("conformance with the real Studio runtime (contract r17 complete custom map)", () => {
  it("is a Studio-generated fixture of a Studio-minted unit", () => {
    expect(fixture.schemaVersion).toBe("tig-product-face-conformance-v1");
    expect(fixture.provenance.generator).toBe(
      "scripts/qa/product-face-conformance-fixtures.mjs",
    );
    expect(fixture.provenance.studioCommit).toMatch(/^[0-9a-f]{40}$/);
    for (const key of MINT_KEYS) {
      expect(fixture.settle.fresh.custom).toHaveProperty(key);
      expect(fixture.transferRequest.fresh.custom).toHaveProperty(key);
    }
    // The registry parser accepts the inspected templates as they are.
    expect(binding.settle).toMatchObject({ preserveUnlisted: true });
    expect(binding.transferRequest).toMatchObject({
      action: "update",
      targetStates: ["Transfer pending"],
      preserveUnlisted: true,
    });
    // The mint keys are not governed: they are copied, never listed.
    for (const key of MINT_KEYS) {
      expect(
        Object.keys(binding.transferRequest!.leaves).some((leaf) =>
          leaf.startsWith(`data.custom.${key}`),
        ),
      ).toBe(false);
    }
  });

  it("accepts the runtime's real settle proposal and request step", () => {
    expect(
      settleCheck(fixture.settle.proposal, fixture.settle.fresh.custom),
    ).toBe("ok");
    expect(
      requestCheck(
        fixture.transferRequest.proposal,
        fixture.transferRequest.fresh.custom,
      ),
    ).toBe("ok");
    // Each under the other's template is refused.
    expect(
      settleCheck(
        {
          ...fixture.transferRequest.proposal,
          operation_id: fixture.settle.proposal.operation_id,
        },
        fixture.transferRequest.fresh.custom,
      ),
    ).not.toBe("ok");
  });

  const tampered: Array<[string, (custom: Custom) => void]> = [
    ["a mint key changed", (c) => edit(c, "activation_hash", "0".repeat(64))],
    [
      "a nested mint key changed",
      (c) => edit(c, "dual_asset.title", "Something else"),
    ],
    ["a mint key dropped", (c) => edit(c, "forge_receipt_hash", REMOVE)],
    ["a nested mint key dropped", (c) => edit(c, "dual_asset.rights", REMOVE)],
    ["a governed leaf changed", (c) => edit(c, "serialNumber", "ARC-9999")],
    [
      "a governed literal changed",
      (c) => edit(c, "receipt.label", "Something else"),
    ],
    [
      "a governed leaf dropped",
      (c) => edit(c, "proof_event.event_hash", REMOVE),
    ],
    ["an extra key added", (c) => edit(c, "extra", "added")],
    ["an extra nested key added", (c) => edit(c, "dual_asset.extra", "added")],
  ];

  it.each(tampered)("refuses a settle with %s", (_label, change) => {
    expect(
      settleCheck(
        variant(fixture.settle.proposal, change),
        fixture.settle.fresh.custom,
      ),
    ).toBe("rejected");
  });

  it.each(tampered)("refuses a request step with %s", (_label, change) => {
    expect(
      requestCheck(
        variant(fixture.transferRequest.proposal, change),
        fixture.transferRequest.fresh.custom,
      ),
    ).toBe("rejected");
  });

  it("refuses when the host's fresh read has a key the proposal does not carry", () => {
    expect(
      requestCheck(fixture.transferRequest.proposal, {
        ...fixture.transferRequest.fresh.custom,
        added_later: "x",
      }),
    ).toBe("rejected");
    expect(
      settleCheck(fixture.settle.proposal, {
        ...fixture.settle.fresh.custom,
        activation_hash: "1".repeat(64),
      }),
    ).toBe("rejected");
  });

  it("a hosted-size unit (64 top-level custom keys, deep nesting) passes within every bound", () => {
    // Root's hosted Tidewell unit has 57 top-level custom keys. Pad the real
    // unit beyond that, as the runtime would copy them (identical in the
    // fresh read and the proposal), including deeply nested values.
    const pad = (custom: Custom) => {
      for (
        let index = 0;
        custom && Object.keys(custom).length < 64;
        index += 1
      ) {
        custom[`hosted_extra_${String(index).padStart(2, "0")}`] =
          index % 3 === 0
            ? {
                a: {
                  b: {
                    c: {
                      d: { e: { f: { g: { h: { i: `deep-${index}` } } } } },
                    },
                  },
                },
              }
            : index % 3 === 1
              ? Array.from({ length: 8 }, (_, item) => `value-${index}-${item}`)
              : `hosted value ${index} `.repeat(8);
      }
      return custom;
    };
    const requestFresh = pad(clone(fixture.transferRequest.fresh.custom));
    const request = variant(fixture.transferRequest.proposal, (custom) =>
      pad(custom),
    );
    expect(Object.keys(requestFresh).length).toBeGreaterThanOrEqual(64);
    expect(Object.keys(request.input.data.custom).length).toBe(
      Object.keys(requestFresh).length,
    );
    expect(requestCheck(request, requestFresh)).toBe("ok");
    const settleFresh = pad(clone(fixture.settle.fresh.custom));
    const settle = variant(fixture.settle.proposal, (custom) => pad(custom));
    expect(settleCheck(settle, settleFresh)).toBe("ok");
    // A deep value moved is still refused.
    expect(
      requestCheck(
        variant(request, (custom) =>
          edit(custom, "hosted_extra_00.a.b.c.d.e.f.g.h.i", "moved"),
        ),
        requestFresh,
      ),
    ).toBe("rejected");
    // The runtime answers stay well inside the BFF's bounded read (a quarter).
    for (const answer of [request, settle]) {
      const bytes = Buffer.byteLength(JSON.stringify({ ok: true, ...answer }));
      expect(bytes).toBeLessThan(MAX_RESPONSE_BYTES / 4);
    }
    // The registry carries governed leaves only, whatever the unit's size:
    // two programmes with both templates use a fraction of its bound.
    const registry = JSON.stringify([
      bindingInput({
        canonicalRegistration: fixture.canonicalRegistration,
        settle: fixture.templates.settle,
        transferRequest: fixture.templates.transferRequest,
      }),
      bindingInput({
        slug: "tidewell",
        canonicalRegistration: fixture.canonicalRegistration,
        settle: fixture.templates.settle,
        transferRequest: fixture.templates.transferRequest,
      }),
    ]);
    expect(registry.length).toBeLessThan(MAX_RAW_BYTES / 2);
    expect(
      parseProductFaceApplications(registry, { production: true }),
    ).toHaveLength(2);
  });
});
